style.css:
@-moz-document domain("pinterest.com") {
/* Fondo con tu imagen */
  body {
    background-image: url("https://i.pinimg.com/736x/3a/7b/f6/3a7bf650cd75eed8b63b2b9c27559513.jpg");
    background-size: cover;
    background-attachment: fixed;
    background-position: center;
    background-repeat: no-repeat;
  }

  /* Capa semitransparente lila para dar tono suave */
  body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(180, 140, 220, 0.35);
    z-index: -1;
  }

  /* Fondo de pines y secciones más transparente, para que se vea el fondo */
  div, section, main, footer, header {
    background-color: rgba(255, 255, 255, 0.8) !important;
    backdrop-filter: blur(4px);
  }

  /* Textos con un leve tono lila */
  h1, h2, h3, h4, h5, h6, p, span, a {
    color: #5b3b7d !important;
  }

  /* Botones */
  button {
    background-color: #b48fd8 !important;
    color: white !important;
    border-radius: 8px !important;
    transition: 0.3s ease;
  }

  button:hover {
    background-color: #cba8f0 !important;
  }

  /* Cuadros de los pines */
  [data-test-id="pin"], [data-test-id="pinWrapper"] {
    background-color: rgba(255, 255, 255, 0.85) !important;
    border-radius: 16px !important;
  }

  /* Cuadro de búsqueda */
  input {
    background-color: rgba(255, 255, 255, 0.9) !important;
    color: #4c2e6b !important;
    border-radius: 20px !important;
  }

  input::placeholder {
    color: #9c84bd !important;
  }

  /* Cabecera */
  header {
    background-color: rgba(255, 255, 255, 0.85) !important;
    backdrop-filter: blur(6px);
  }
}
